effort_codes = dict(n='none', l='low', m='medium', h='high', x='xhigh')

def effort_code(v):
    "The effort code (`n l m h x`) for an effort name, code, or level 0-3"
    if isinstance(v, int): return 'lmhx'[v]
    return {**{v:k for k,v in effort_codes.items()}, 'max':'x'}.get(v, v)

def effort_levels(info):
    "Ordered reasoning effort levels a model accepts, lowest first, from its metadata `info`; empty when it does not reason"
    if not info.get('supports_reasoning'): return []
    if lv := info.get('reasoning_effort_levels'): return list(lv)
    lv = ['low', 'medium', 'high']
    if info.get('supports_none_reasoning_effort'): lv.insert(0, 'none')
    if info.get('supports_xhigh_reasoning_effort'): lv.append('xhigh')
    if info.get('supports_max_reasoning_effort'): lv.append('max')
    return lv

def resolve_effort(levels, effort):
    "The level among ordered `levels` that `effort` (a code `n l m h x`, a name, or a level 0-3) selects; None when `n` has no `none` level"
    code = effort_code(effort)
    lv = [o for o in levels if o != 'none']
    if code not in effort_codes: return effort
    if not lv: return effort if isinstance(effort, int) else effort_codes[code]
    if code == 'n': return 'none' if 'none' in levels else None
    if code == 'x': return lv[-1]
    return lv[min('lmh'.index(code), len(lv)-1)]


