def get_model_pricing(mn, vendor_name, million=True):
    return {k:round(v * (1e6 if million else 1), 6) for k,v in get_model_info(mn, vendor_name).items()
        if 'cost' in k and isinstance(v,float) and 'priority' not in k}

# %% ../nbs/00_types.ipynb #79304cd9
def approx_pricing(nm, vendor_name, out=10, cache=80, inp=10, markup=0):
    "Approx cost per million tokens with given output/cache/input proportions"
    p = get_model_pricing(nm, vendor_name)
    ic = p.get('cache_creation_input_token_cost', p['input_cost_per_token'])
    res = (p['output_cost_per_token']*out + p['cache_read_input_token_cost']*cache + ic*inp) / (out+cache+inp)
    if vendor_name=='anthropic': res *= 1.5
    return res*(1+markup)

# %% ../nbs/00_types.ipynb #d2a310fb
def is_deepseek_peak_hour(dt=None):
    "Check whether current UTC time is in DeepSeek peak pricing hours."
    dt = dt or datetime.now(timezone.utc)
    h = dt.hour + dt.minute/60
    return 1 <= h < 4 or 6 <= h < 10

# %% ../nbs/00_types.ipynb #4c701619
def price_tier(meta, n):
    "Suffix of the pricing tier applying to `n` prompt tokens, or '' for base rates."
    o = first(o for k in meta if (o:=re.match(r'input_cost_per_token(_above_(\d+)k_tokens)$', k)))
    return o[1] if o and n>int(o[2])*1000 else ''

# %% ../nbs/00_types.ipynb #956d2495
def tier_rate(meta, key, tier):
    "Rate for `key` at `tier`, falling back to the base key."
    return meta.get(f'{key}{tier}') or meta[key]

